git remote -v; echo "remotes: $?"; cat .gitignore; echo ---; cat > spec/cancel.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); o=$(mktemp); e=$(mktemp)
printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\tz\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header row removed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00.10:00.z$' "$t" || { echo "other room's booking at the same time removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00.14:00.y$' "$t" || { echo "other booking removed"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >"$o" 2>"$e"; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ ! -s "$o" ] || { echo "not found should print nothing to stdout"; fail=1; }
grep -q '^not found: aoi 2026-01-05 11:00$' "$e" || { echo "not found message should go to stderr"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >"$o" 2>"$e"; [ $? = 2 ] || { echo "wrong arg count should exit 2"; fail=1; }
[ ! -s "$o" ] || { echo "usage should print nothing to stdout"; fail=1; }
grep -q '^usage: cancel.sh ROOM DATE START$' "$e" || { echo "usage message should go to stderr"; fail=1; }
rm -f "$t" "$o" "$e"; exit $fail
EOF
bash spec/cancel.spec.sh; echo "spec exit (expect 1, red before fix): $?"; bash tools/check; echo "check exit: $?"

